  "source": "def settle(charges, slots):
    weights = {}
    caps = {}
    allocation = {name: 0 for name in charges}
    for name, value in charges.items():
        if isinstance(value, int):
            weights[name] = value
            caps[name] = None
        else:
            weights[name] = value['weight']
            caps[name] = value['cap']
    remaining = slots
    while remaining > 0:
        eligible = [name for name in charges if weights[name] > 0 and (caps[name] is None or allocation[name] < caps[name])]
        if not eligible:
            break
        total = sum(weights[name] for name in eligible)
        proposals = {}
        remainders = {}
        for name in eligible:
            proposals[name], remainders[name] = divmod(remaining * weights[name], total)
        extra = remaining - sum(proposals.values())
        order = sorted(eligible, key=lambda name: (-remainders[name], name))
        for name in order[:extra]:
            proposals[name] += 1
        for name in eligible:
            grant = proposals[name]
            if caps[name] is not None:
                grant = min(grant, caps[name] - allocation[name])
            allocation[name] += grant
            remaining -= grant
    return allocation",
